// SubmitBatch is the resolver for the submitBatch field.
func (r *mutationResolver) SubmitBatch(ctx context.Context, input model.SubmitBatchInput) (*model.BatchResult, error) {
	startTime := time.Now()

	// Calculate total items
	totalItems := len(input.Messages) + len(input.Events)
	if totalItems == 0 {
		return &model.BatchResult{
			TotalItems:   0,
			SuccessCount: 0,
			FailureCount: 0,
			Results:      []model.BatchItemResult{},
			DurationMs:   0,
		}, nil
	}

	// Enforce max batch size (prevent DoS)
	const maxBatchSize = 1000
	if totalItems > maxBatchSize {
		return nil, fmt.Errorf("batch size %d exceeds maximum of %d", totalItems, maxBatchSize)
	}

	stopOnError := input.StopOnError != nil && *input.StopOnError
	parallel := input.Parallel != nil && *input.Parallel

	results := make([]model.BatchItemResult, 0, totalItems)
	var successCount, failureCount int

	// Process messages
	if len(input.Messages) > 0 {
		messageResults := r.processBatchMessages(ctx, input.Messages, stopOnError, parallel)
		for _, res := range messageResults {
			if res.Success {
				successCount++
			} else {
				failureCount++
			}
		}
		results = append(results, messageResults...)

		// Check stop on error
		if stopOnError && failureCount > 0 {
			return &model.BatchResult{
				TotalItems:   totalItems,
				SuccessCount: successCount,
				FailureCount: failureCount,
				Results:      results,
				DurationMs:   int(time.Since(startTime).Milliseconds()),
			}, nil
		}
	}

	// Process pre-parsed events
	if len(input.Events) > 0 {
		// Adjust indices to continue from messages
		baseIndex := len(input.Messages)
		eventResults := r.processBatchEvents(ctx, input.Events, baseIndex, stopOnError, parallel)
		for _, res := range eventResults {
			if res.Success {
				successCount++
			} else {
				failureCount++
			}
		}
		results = append(results, eventResults...)
	}

	return &model.BatchResult{
		TotalItems:   totalItems,
		SuccessCount: successCount,
		FailureCount: failureCount,
		Results:      results,
		DurationMs:   int(time.Since(startTime).Milliseconds()),
	}, nil
}

// TriggerWorkflow is the resolver for the triggerWorkflow field.
func (r *mutationResolver) TriggerWorkflow(ctx context.Context, name string, event map[string]any) (*model.WorkflowResult, error) {
	if r.WorkflowEngine == nil {
		return nil, fmt.Errorf("workflow engine not configured")
	}

	// Process the event through the workflow engine
	// The engine accepts interface{}, so we can pass the map directly
	startTime := time.Now()
	wfResult := r.WorkflowEngine.ProcessWithContext(ctx, event)
	duration := time.Since(startTime).Milliseconds()

	// Collect matched routes and actions
	routesMatchedCount := 0
	actionsExecutedCount := 0
	var errors []string
	var routeNames []string
	var actionsSummary []string

	for _, rr := range wfResult.RouteResults {
		if rr.Matched {
			routesMatchedCount++
			routeNames = append(routeNames, rr.RouteName)
			actionsExecutedCount += rr.ActionsRun
			// Record how many actions ran for this route
			if rr.ActionsRun > 0 {
				actionsSummary = append(actionsSummary, fmt.Sprintf("%s:%d", rr.RouteName, rr.ActionsRun))
			}
			for _, err := range rr.ActionErrors {
				errors = append(errors, err.Error())
			}
			for _, err := range rr.TransformErrors {
				errors = append(errors, err.Error())
			}
		}
	}

	// Broadcast to workflow event subscribers
	notification := &model.WorkflowEventNotification{
		Event:           nil, // Raw map can't be converted to Event interface
		Workflow:        name,
		RoutesMatched:   routeNames,
		ActionsExecuted: actionsSummary,
		Duration:        int(duration),
	}
	r.broadcastWorkflowEvent(notification)

	return &model.WorkflowResult{
		WorkflowName:    name,
		RoutesMatched:   routesMatchedCount,
		ActionsExecuted: actionsExecutedCount,
		Errors:          errors,
		Duration:        int(duration),
	}, nil
}

