// ParsePreview is the resolver for the parsePreview field.
func (r *queryResolver) ParsePreview(ctx context.Context, format model.SourceFormat, data string, source *string) (*model.ParseResult, error) {
	result := &model.ParseResult{
		Events:   []model.Event{},
		Warnings: []model.ParseWarning{},
		Errors:   []string{},
	}

	src := "preview"
	if source != nil {
		src = *source
	}

	var parsedEvents []interface{}

	switch format {
	case model.SourceFormatHL7v2:
		parser := hl7v2.NewParser(src, hl7v2.ParserConfig{})
		parseResult, err := parser.ParseWithResult(data)
		if err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result, nil
		}
		if parseResult.Event != nil {
			parsedEvents = append(parsedEvents, parseResult.Event)
		}
		for _, w := range parseResult.Warnings {
			result.Warnings = append(result.Warnings, model.ParseWarning{
				Phase:   w.Phase,
				Code:    w.Code,
				Message: w.Message,
				Path:    strPtr(w.Path),
			})
		}

	case model.SourceFormatFHIR:
		parser := fhir.NewParser(src)
		parseResult, err := parser.ParseWithResult([]byte(data))
		if err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result, nil
		}
		parsedEvents = parseResult.Events
		for _, w := range parseResult.Warnings {
			result.Warnings = append(result.Warnings, model.ParseWarning{
				Phase:   w.Phase,
				Code:    w.Code,
				Message: w.Message,
			})
		}

	case model.SourceFormatCSV:
		parser := csv.NewParser(src, csv.ParserConfig{})
		parseResult, err := parser.Parse(bytes.NewReader([]byte(data)))
		if err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result, nil
		}
		parsedEvents = parseResult.Events
		for _, w := range parseResult.Warnings {
			result.Warnings = append(result.Warnings, model.ParseWarning{
				Phase:   w.Phase,
				Code:    w.Code,
				Message: w.Message,
				Path:    strPtr(w.Path),
			})
		}

	case model.SourceFormatCDA:
		parser := cda.NewParser(src, nil)
		doc, err := parser.Parse([]byte(data))
		if err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result, nil
		}
		mapper := cda.NewMapper(nil)
		mapResult, err := mapper.Map(doc)
		if err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result, nil
		}
		parsedEvents = mapResult.Events

	case model.SourceFormatEDI837, model.SourceFormatEDI835:
		parser := edi.NewParser()
		parseResult, err := parser.Parse(data)
		if err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result, nil
		}
		// Convert EDI interchange to events using mappers
		if parseResult.Interchange != nil {
			for _, fg := range parseResult.Interchange.FunctionalGroups {
				for _, tx := range fg.Transactions {
					var evts []interface{}
					switch tx.SetIdentifier {
					case "837":
						claims, mapErr := edi.Map837ToEvents(tx, src)
						if mapErr == nil {
							for _, c := range claims {
								evts = append(evts, c)
							}
						}
					case "835":
						rems, mapErr := edi.Map835ToEvents(tx, src)
						if mapErr == nil {
							for _, r := range rems {
								evts = append(evts, r)
							}
						}
					}
					parsedEvents = append(parsedEvents, evts...)
				}
			}
		}
		for _, w := range parseResult.Warnings {
			result.Warnings = append(result.Warnings, model.ParseWarning{
				Phase:   w.Phase,
				Code:    w.Code,
				Message: w.Message,
			})
		}

	default:
		result.Errors = append(result.Errors, fmt.Sprintf("unsupported format: %s", format))
		return result, nil
	}

	// Convert to GraphQL events
	for _, evt := range parsedEvents {
		gqlEvent := convertToGraphQLEvent(evt, src, format, nil)
		if gqlEvent != nil {
			result.Events = append(result.Events, gqlEvent)
		}
	}

	result.Success = len(result.Errors) == 0
	return result, nil
}

